import {
  coreBlockContractDefinitions,
  collectionEntryDraftSchema,
  createContentBlockSchema,
  createPageDraftSchema,
  createPublicationSnapshotSchema,
  sitePackageDescriptorSchema,
  type CmsBlockContractDefinition,
} from '@web-app-demo/contracts'
import { z } from 'zod'

const editableText = (maximumLength: number) => z.string().trim().min(1).max(maximumLength)

export const estimateCalculatorDataSchema = z.object({
  title: editableText(160),
  description: editableText(1_000),
  unitPrice: z.number().finite().positive().max(1_000_000),
  minimumPrice: z.number().finite().nonnegative().max(100_000_000),
  minimumArea: z.number().finite().positive().max(100_000),
  maximumArea: z.number().finite().positive().max(100_000),
}).strict().superRefine((data, context) => {
  if (data.maximumArea < data.minimumArea) {
    context.addIssue({
      code: 'custom',
      message: 'Максимальная площадь не может быть меньше минимальной',
      path: ['maximumArea'],
    })
  }
})

export const selectedSitePackageDescriptor = sitePackageDescriptorSchema.parse({
  id: 'reference-calculator',
  version: '1.0.0',
  schemaVersion: 1,
})

export const estimateCalculatorDefinition = {
  type: 'estimateCalculator',
  label: 'Калькулятор стоимости',
  description: 'Предварительный расчёт по площади и цене за м²',
  dataSchema: estimateCalculatorDataSchema,
  defaultData: {
    title: 'Рассчитайте стоимость',
    description: 'Укажите площадь, чтобы узнать предварительную стоимость.',
    unitPrice: 1_800,
    minimumPrice: 15_000,
    minimumArea: 5,
    maximumArea: 300,
  },
  editor: {
    kind: 'descriptor',
    fields: [
      { key: 'title', kind: 'text', label: 'Заголовок', required: true, min: 1, max: 160 },
      { key: 'description', kind: 'text', label: 'Описание', required: true, min: 1, max: 1_000 },
      { key: 'unitPrice', kind: 'number', label: 'Цена за м²', required: true, min: 1, max: 1_000_000 },
      { key: 'minimumPrice', kind: 'number', label: 'Минимальная стоимость', required: true, min: 0, max: 100_000_000 },
      { key: 'minimumArea', kind: 'number', label: 'Минимальная площадь', required: true, min: 0.1, max: 100_000 },
      { key: 'maximumArea', kind: 'number', label: 'Максимальная площадь', required: true, min: 0.1, max: 100_000 },
    ],
  },
} satisfies CmsBlockContractDefinition

export const selectedBlockDefinitions = [
  ...coreBlockContractDefinitions,
  estimateCalculatorDefinition,
] satisfies readonly CmsBlockContractDefinition[]

export const selectedContentBlockSchema = createContentBlockSchema(selectedBlockDefinitions)
export const selectedPageDraftSchema = createPageDraftSchema(selectedContentBlockSchema)
export const selectedSitePackageSchemaOneValidation = {
  pageDraftSchema: selectedPageDraftSchema,
  contentEntryDraftSchema: collectionEntryDraftSchema,
  menuDraftSchema: z.object({
    items: z.array(z.object({
      label: z.string().trim().min(1).max(120),
      href: z.string().trim().min(1).max(500),
    }).strict()).max(100),
    expectedRevision: z.number().int().nonnegative(),
  }).strict(),
  siteSettingsDraftSchema: z.object({
    companyName: z.string().trim().min(1).max(160),
    expectedRevision: z.number().int().nonnegative(),
  }).strict(),
} as const
export const selectedPublicationSnapshotSchema = createPublicationSnapshotSchema(selectedContentBlockSchema)
export const selectedSitePackageMigrations = [] as const

export type EstimateCalculatorData = z.output<typeof estimateCalculatorDataSchema>
export type SelectedPageDraft = z.output<typeof selectedPageDraftSchema>
